const item = $input.first().json;
let chatId = '';
let messageId = null;
let text = '';
let callbackData = '';
let callbackId = '';
let fromUser = null;

if (item.callback_query) {
  const cq = item.callback_query;
  chatId = String(cq.message && cq.message.chat ? cq.message.chat.id : '');
  messageId = cq.message ? cq.message.message_id : null;
  callbackData = cq.data || '';
  callbackId = cq.id || '';
  fromUser = cq.from || null;
} else if (item.message) {
  chatId = String(item.message.chat ? item.message.chat.id : '');
  messageId = item.message.message_id || null;
  text = (item.message.text || '').trim();
  fromUser = item.message.from || null;
}

let type = 'help_unknown';
let url = '';
let materialId = '';
let qIdx = -1;
let choice = '';

if (callbackData) {
  if (callbackData.indexOf('pick:') === 0) {
    type = 'pickMaterial';
    materialId = callbackData.slice(5);
  } else if (callbackData.indexOf('ans:') === 0) {
    type = 'answer';
    const parts = callbackData.split(':');
    qIdx = parseInt(parts[1], 10);
    choice = (parts[2] || '').toUpperCase();
  }
} else if (text) {
  if (text === '/start' || text.indexOf('/start ') === 0 || text.indexOf('/start@') === 0) {
    type = 'start';
  } else if (text === '/quiz' || text.indexOf('/quiz ') === 0 || text.indexOf('/quiz@') === 0) {
    type = 'quiz';
  } else if (text.indexOf('/learn') === 0) {
    const candidate = text.replace(/^\/learn(@\S+)?\s*/, '').trim();
    if (/^https?:\/\/\S+/i.test(candidate)) {
      type = 'learn';
      url = candidate.split(/\s+/)[0];
    } else {
      type = 'help_learn';
    }
  }
}

return [{
  json: {
    chatId: chatId,
    messageId: messageId,
    text: text,
    callbackData: callbackData,
    callbackId: callbackId,
    fromUser: fromUser,
    type: type,
    url: url,
    materialId: materialId,
    qIdx: qIdx,
    choice: choice
  }
}];

const ctx = $('Normalize Update').first().json;
let text;
if (ctx.type === 'help_learn') {
  text = 'To add learning material, send the command followed by a URL, for example:\n/learn https://example.com/article';
} else {
  text = 'I did not recognize that command. Try /start, /learn <url>, or /quiz.';
}
return [{ json: { method: 'sendMessage', body: { chat_id: ctx.chatId, text: text } } }];

const html = String($json.data || $json.body || $json.text || '');
const titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
let title = titleMatch ? titleMatch[1].replace(/\s+/g, ' ').trim() : '';
let text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'")
  .replace(/&#(\d+);/g, function (_, n) { return String.fromCharCode(parseInt(n, 10)); })
  .replace(/\s+/g, ' ')
  .trim();
const content = text.slice(0, 12000);
const ctx = $('Normalize Update').first().json;
if (!title) {
  title = content.split(/[.\n]/)[0].slice(0, 80) || 'Untitled material';
}
return [{ json: { chatId: ctx.chatId, url: ctx.url, title: title, content: content } }];

function parseJson(raw) {
  if (raw == null) return {};
  if (typeof raw === 'object') return raw;
  const str = String(raw);
  try { return JSON.parse(str); } catch (e) {}
  const m = str.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch (e) {} }
  return {};
}

const raw = $json.message && $json.message.content !== undefined ? $json.message.content : ($json.content || $json.text || $json.output || '');
const parsed = parseJson(raw);

const ctx = $('Strip HTML').first().json;
const data = $getWorkflowStaticData('global');
if (!data.users) data.users = {};
if (!data.users[ctx.chatId]) data.users[ctx.chatId] = { materials: [], activeQuiz: null, counter: 0 };
const u = data.users[ctx.chatId];
u.counter += 1;
const id = 'LM-' + String(u.counter).padStart(3, '0');

const summaryArr = Array.isArray(parsed.summary) ? parsed.summary.map(function (s) { return String(s).trim(); }).filter(Boolean) : [];
const conceptsArr = Array.isArray(parsed.concepts) ? parsed.concepts.map(function (s) { return String(s).trim(); }).filter(Boolean) : [];

const material = {
  id: id,
  url: ctx.url || '',
  title: String(parsed.title || ctx.title || 'Untitled').trim().slice(0, 200),
  content: ctx.content,
  summary: summaryArr,
  concepts: conceptsArr,
  difficulty: String(parsed.difficulty || 'unknown'),
  addedDate: new Date().toISOString()
};
u.materials.push(material);

const summaryLines = summaryArr.length
  ? summaryArr.map(function (s, i) { return (i + 1) + '. ' + s; }).join('\n')
  : '(no summary produced)';
const conceptsLine = conceptsArr.length ? conceptsArr.join(', ') : 'n/a';

const lines = [
  material.title,
  'Difficulty: ' + material.difficulty,
  material.url ? ('Source: ' + material.url) : null,
  '',
  'Key points:',
  summaryLines,
  '',
  'Main concepts: ' + conceptsLine,
  '',
  'Saved as ' + id + '. Tap the button below to take a quiz on this material, or send /quiz any time.'
].filter(function (x) { return x !== null; });
const text = lines.join('\n').slice(0, 3800);

const body = {
  chat_id: ctx.chatId,
  text: text,
  reply_markup: {
    inline_keyboard: [[
      { text: 'Take a quiz on this material', callback_data: 'pick:' + id }
    ]]
  }
};

return [{ json: { method: 'sendMessage', body: body } }];

const ctx = $('Normalize Update').first().json;
const data = $getWorkflowStaticData('global');
const u = data.users && data.users[ctx.chatId];

if (!u || !u.materials || u.materials.length === 0) {
  return [{ json: { method: 'sendMessage', body: { chat_id: ctx.chatId, text: 'You have no saved materials yet. Send /learn <url> first to add some.' } } }];
}

const recent = u.materials.slice(-20);
const buttons = recent.map(function (m) {
  const label = (m.id + ': ' + (m.title || '').replace(/\s+/g, ' ').trim()).slice(0, 60);
  return [{ text: label, callback_data: 'pick:' + m.id }];
});

const body = {
  chat_id: ctx.chatId,
  text: 'Pick a topic for your quiz:',
  reply_markup: { inline_keyboard: buttons }
};

return [{ json: { method: 'sendMessage', body: body } }];

const ctx = $('Normalize Update').first().json;
const data = $getWorkflowStaticData('global');
const u = data.users && data.users[ctx.chatId];
const m = u && Array.isArray(u.materials) ? u.materials.find(function (x) { return x.id === ctx.materialId; }) : null;

if (!m) {
  return [{ json: { chatId: ctx.chatId, missing: true, materialId: ctx.materialId, title: '', content: '' } }];
}

return [{ json: { chatId: ctx.chatId, missing: false, materialId: m.id, title: m.title, content: m.content } }];

function parseJson(raw) {
  if (raw == null) return {};
  if (typeof raw === 'object') return raw;
  const str = String(raw);
  try { return JSON.parse(str); } catch (e) {}
  const m = str.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch (e) {} }
  return {};
}

const raw = $json.message && $json.message.content !== undefined ? $json.message.content : ($json.content || $json.text || $json.output || '');
const parsed = parseJson(raw);

const ctx = $('Load Material').first().json;
const data = $getWorkflowStaticData('global');
if (!data.users) data.users = {};
if (!data.users[ctx.chatId]) data.users[ctx.chatId] = { materials: [], activeQuiz: null, counter: 0 };
const u = data.users[ctx.chatId];

if (ctx.missing) {
  return [{ json: { method: 'sendMessage', body: { chat_id: ctx.chatId, text: 'That material was not found. It may have been removed. Send /quiz to pick another, or /learn <url> to add new material.' } } }];
}

let questions = Array.isArray(parsed.questions) ? parsed.questions : (Array.isArray(parsed) ? parsed : []);
questions = questions.slice(0, 5).map(function (q, i) {
  const opts = q.options || {};
  return {
    id: 'Q' + (i + 1),
    question: String(q.question || '').trim(),
    options: {
      A: String(opts.A || q.optionA || '').trim(),
      B: String(opts.B || q.optionB || '').trim(),
      C: String(opts.C || q.optionC || '').trim(),
      D: String(opts.D || q.optionD || '').trim()
    },
    correctAnswer: String(q.correctAnswer || q.correct || '').toUpperCase().trim().charAt(0),
    explanation: String(q.explanation || '').trim()
  };
}).filter(function (q) { return q.question && q.options.A && q.options.B && q.options.C && q.options.D && /^[A-D]$/.test(q.correctAnswer); });

if (questions.length === 0) {
  return [{ json: { method: 'sendMessage', body: { chat_id: ctx.chatId, text: 'Sorry, I could not generate a quiz for this material. Try /learn with a different URL.' } } }];
}

u.activeQuiz = {
  materialId: ctx.materialId,
  questions: questions,
  currentIndex: 0,
  answers: []
};

const q = questions[0];
const lines = [
  'Quiz on: ' + ctx.title,
  '',
  'Question 1 of ' + questions.length + ':',
  q.question,
  '',
  'A) ' + q.options.A,
  'B) ' + q.options.B,
  'C) ' + q.options.C,
  'D) ' + q.options.D
];
const text = lines.join('\n').slice(0, 3800);

const body = {
  chat_id: ctx.chatId,
  text: text,
  reply_markup: {
    inline_keyboard: [
      [
        { text: 'A', callback_data: 'ans:0:A' },
        { text: 'B', callback_data: 'ans:0:B' }
      ],
      [
        { text: 'C', callback_data: 'ans:0:C' },
        { text: 'D', callback_data: 'ans:0:D' }
      ]
    ]
  }
};

return [{ json: { method: 'sendMessage', body: body } }];

const ctx = $('Normalize Update').first().json;
const data = $getWorkflowStaticData('global');
const u = data.users && data.users[ctx.chatId];

let bodyText;
let replyMarkup = null;

if (!u || !u.activeQuiz) {
  bodyText = 'No active quiz. Send /quiz to start one.';
} else {
  const aq = u.activeQuiz;
  const idx = ctx.qIdx;
  const choice = ctx.choice;
  const q = aq.questions[idx];

  if (!q) {
    bodyText = 'That question is no longer active. Start over with /quiz.';
  } else {
    if (!aq.answers.find(function (a) { return a.idx === idx; })) {
      const correct = String(q.correctAnswer || '').toUpperCase().trim();
      const picked = String(choice || '').toUpperCase().trim();
      aq.answers.push({
        idx: idx,
        questionId: q.id,
        picked: picked,
        correct: correct,
        isCorrect: picked === correct
      });
      aq.currentIndex = idx + 1;
    }

    const next = aq.questions[aq.currentIndex];
    if (next && aq.answers.length < aq.questions.length) {
      const ni = aq.currentIndex;
      const lines = [
        'Question ' + (ni + 1) + ' of ' + aq.questions.length + ':',
        next.question,
        '',
        'A) ' + next.options.A,
        'B) ' + next.options.B,
        'C) ' + next.options.C,
        'D) ' + next.options.D
      ];
      bodyText = lines.join('\n').slice(0, 3800);
      replyMarkup = {
        inline_keyboard: [
          [
            { text: 'A', callback_data: 'ans:' + ni + ':A' },
            { text: 'B', callback_data: 'ans:' + ni + ':B' }
          ],
          [
            { text: 'C', callback_data: 'ans:' + ni + ':C' },
            { text: 'D', callback_data: 'ans:' + ni + ':D' }
          ]
        ]
      };
    } else {
      const total = aq.questions.length;
      const correctCount = aq.answers.filter(function (a) { return a.isCorrect; }).length;
      const score = Math.round((correctCount / total) * 100);
      const out = ['Quiz complete!', 'Score: ' + correctCount + '/' + total + ' (' + score + '%)', ''];
      aq.answers.forEach(function (a) {
        const qq = aq.questions[a.idx];
        if (a.isCorrect) {
          out.push('Q' + (a.idx + 1) + ': Correct (you picked ' + a.picked + ').');
        } else {
          out.push('Q' + (a.idx + 1) + ': Incorrect (you picked ' + (a.picked || '?') + ', correct is ' + a.correct + ').');
          if (qq && qq.explanation) {
            out.push('   Explanation: ' + qq.explanation.slice(0, 240));
          }
        }
      });
      out.push('', 'Send /quiz to try another topic, or /learn <url> to add new material.');
      bodyText = out.join('\n').slice(0, 3800);
      u.activeQuiz = null;
    }
  }
}

const body = { chat_id: ctx.chatId, text: bodyText };
if (replyMarkup) body.reply_markup = replyMarkup;

return [{ json: { method: 'sendMessage', body: body } }];
